# DK HOA.  Hou - Odder - Aarhus H
with detail = 2 {
    let ha = path("d2.dk.hoa");

    with railway = :first :pax :removed {
        with link = "point.dk.Hou" {
            statdot(ha[:hou]);
            slabel(:right, ha[:hou] + (1.5dt, 0.8dt), "Hou");
        }

        with link = "line.dk.HOA" {
            track(ha[:hou, :hou + 5.01km]);
            line_label(:right:sw, ha[:hou + 5km] >> 0.5mt, "HOA");
            track(ha[:hou + 4.99km, :odd.yh]);
            track(ha[:odd.yh, :odd]);
        }
    }

    with railway = :first :cat:dc75 :pax {
        with link = "point.dk.Odder" {
            statdot(ha[:odd]);
            slabel(:left, ha[:odd] + (-1.5dt, 0.8dt), "Odder");
        }

        with link = "line.dk.HOA" {
            track(ha[:odd, :odd + 10.91km]);
            line_label(:right:w, ha[:odd + 10.9km] >> 0.5mt, "HOA");
            track(
                    ha[:odd + 10.89km, :vib.zo - 1md]
                ..  ha[:vib.xo, :vib.yo] >> 0.5md >> 1ms >> 0.5mt
            );
            track(ha[:vib.yo, :aar.yt] >> 0.5md >> 1ms >> 0.5mt);
            with layer = -1 track(
                    ha[:aar.yt - 1.1dl, :aar.yt] >> 0.5md >> 1ms >> 0.5mt
                ..  ha[:aar.yr + 1md, :aar.yr + 1.1md] << 0.5md << 1ms << 0.5mt
            );
            track(ha[:aar.yr + 1md, :aar] << 0.5md << 1ms << 0.5mt);
        }
    }
}


